from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Step 1: Remove any spaces from the input string
    result = []
    start = 0
    count = 0

    for i, char in enumerate(paren_string):
        if char == '(':
            count += 1
            if count == 1:
                start = i
        elif char == ')':
            count -= 1
            if count == 0:
                result.append(paren_string[start:i+1])  # Step 2: Identify and extract each group of nested parentheses

    return result  # Step 3: Separate each group into separate strings

